// RunDue attempts every delivery that is due at the clock's time and returns how many attempts it made. An answer with a 2xx
// status succeeds the delivery. A failed attempt leaves it pending for a retry, until the 7th failure fails it for good; a
// 410 Gone answer fails it for good at once and disables the endpoint.
func (s *Service) RunDue(ctx context.Context) (int, error) {
	n := 0
	for _, d := range s.store.DueDeliveries(s.clock.Now()) {
		if err := ctx.Err(); err != nil {
			return n, err
		}
		if s.deliver(ctx, d) {
			n++
		}
	}
	return n, nil
}

