286		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
287		defer cancel()
288		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
289		if err != nil {
290			return 0, err.Error()
291		}
292		req.Header.Set("Content-Type", "application/json")
293		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
294		req.Header.Set("Tally-Event-Id", e.ID)
295		req.Header.Set("Tally-Event-Type", e.Type)
296		req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
297		const slow = "the endpoint took longer than 10 seconds"
298		resp, err := s.doer.Do(req)
299		if err != nil {
300			if errors.Is(ctx.Err(), context.DeadlineExceeded) {
301				return 0, slow
302			}
303			return 0, err.Error()
304		}
305		defer resp.Body.Close()
306		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
307		if errors.Is(ctx.Err(), context.DeadlineExceeded) {
308			return 0, slow
309		}
310		if resp.StatusCode < 200 || resp.StatusCode > 299 {
311			return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
312		}
313		return resp.StatusCode, ""
314	}
315

155	}
